"use strict";
// The Filled AFE Form.
//
// Page 1 is the Global AFE Template's own AFE Form sheet, reproduced from the template rather
// than approximated: lib/pdf/afeFormLayout.js is generated by tools/build_afe_form.py from the
// template and the PDF Excel prints from it, so every rule, tint, label and font size sits
// where Acme's own form puts it, on the same A4 page. This file draws that data and fills
// in the boxes the tool owns. The pages after it come from lib/pdf/extraPages.js.
//
// The type is Carlito (lib/pdf/assets), which is metrically identical to the template's
// Calibri and licensed OFL, so line breaks and column fits match without shipping Calibri.
//
// Determinism matters more than it looks: the bytes are hashed at send (`formHash`) to prove
// that what an approver signed is what the tool renders now. Fixed document dates, standard
// subsetting, no clock, no randomness — same AFE in, same bytes out.
const crypto = require("crypto");
const fs = require("fs");
const path = require("path");
const { PDFDocument, rgb } = require("pdf-lib");
const fontkit = require("@pdf-lib/fontkit");
const layout = require("./afeFormLayout");
const extra = require("./extraPages");
const { buildFormModel, formDate, money: money2 } = require("./formModel");

const PAGE = layout.PAGE;
const INK = extra.INK;
const SIZE = extra.SIZE;
const colour = (c) => rgb(c[0], c[1], c[2]);
const hex = (h) => rgb(parseInt(h.slice(1, 3), 16) / 255, parseInt(h.slice(3, 5), 16) / 255, parseInt(h.slice(5, 7), 16) / 255);

// Read once, at load: the same bytes every render.
const FONT_BYTES = {
  regular: fs.readFileSync(path.join(__dirname, "assets", "Carlito-Regular.ttf")),
  bold: fs.readFileSync(path.join(__dirname, "assets", "Carlito-Bold.ttf")),
};

// A fixed document date. The form is hashed and compared later; a clock in the metadata would
// change the bytes on every render and break that comparison for no gain.
const DOC_DATE = new Date(Date.UTC(2026, 0, 1, 0, 0, 0));

// The vendored font carries WinAnsi — Latin-1 plus CP1252's punctuation, which is exactly
// what tools/build_form_font.py cuts it down to. The form's own footnotes are set with en
// dashes and an approver's name can carry accents, so those are printed rather than folded;
// only a character the font genuinely lacks is replaced, so an unexpected glyph degrades
// instead of throwing mid-render.
const EXTRA = "€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ";
const PRINTABLE = new RegExp("^[\\x20-\\x7e\\u00a1-\\u00ff" + EXTRA + "]*$");
// A minus sign is not an en dash and a soft hyphen is not ink; a tab has no meaning here.
const TYPO = { "−": "–", " ": " ", "­": "", "\t": " " };
function winAnsi(input) {
  if (input === null || input === undefined) return "";
  let out = "";
  for (const ch of String(input)) {
    const mapped = TYPO[ch] !== undefined ? TYPO[ch] : ch;
    const stripped = mapped.normalize("NFC");
    out += PRINTABLE.test(stripped) ? stripped : "?";
  }
  return out;
}

// ---- drawing helpers ----------------------------------------------------------------------
function makeCanvas(doc, fonts) {
  let page = null;
  const api = {
    newPage() { page = doc.addPage([PAGE.width, PAGE.height]); return api; },
    /** A landscape page. Eleven years of figures do not fit across a portrait A4 (R94). */
    newLandscapePage() { page = doc.addPage([PAGE.height, PAGE.width]); return api; },
    get page() { return page; },
    /** Draw onto a page that already exists — the footers, once the count is settled. */
    usePage(p) { page = p; return api; },
    width(text, size, bold) { return (bold ? fonts.bold : fonts.regular).widthOfTextAtSize(winAnsi(text), size); },
    /** Greedy wrap on spaces, honouring hard newlines; never returns more than `maxLines`. */
    wrap(text, size, bold, maxWidth, maxLines) {
      const font = bold ? fonts.bold : fonts.regular;
      const lines = [];
      for (const paragraph of winAnsi(text).split("\n")) {
        let line = "";
        for (const word of paragraph.split(/\s+/).filter(Boolean)) {
          const next = line ? line + " " + word : word;
          if (font.widthOfTextAtSize(next, size) <= maxWidth || !line) line = next;
          else { lines.push(line); line = word; }
        }
        lines.push(line);
      }
      const out = lines.filter((l, i) => l !== "" || i === 0);
      if (maxLines && out.length > maxLines) {
        const kept = out.slice(0, maxLines);
        kept[maxLines - 1] = kept[maxLines - 1].replace(/.{3}$/, "...");
        return kept;
      }
      return out;
    },
    /** `str`, shortened with an ellipsis until it fits `maxWidth`. */
    fit(str, size, bold, maxWidth) {
      const font = bold ? fonts.bold : fonts.regular;
      const text = winAnsi(str);
      if (!text || maxWidth <= 0 || font.widthOfTextAtSize(text, size) <= maxWidth) return text;
      let lo = 0;
      let hi = text.length;
      while (lo < hi) {
        const mid = Math.ceil((lo + hi) / 2);
        if (font.widthOfTextAtSize(text.slice(0, mid) + "…", size) <= maxWidth) lo = mid; else hi = mid - 1;
      }
      return lo > 0 ? text.slice(0, lo) + "…" : "";
    },
    text(str, o) {
      let s = winAnsi(str);
      if (!s) return;
      const size = o.size || SIZE.value;
      const font = o.bold ? fonts.bold : fonts.regular;
      // `w` has always been advisory here: it positions a right or centre alignment and is
      // ignored for a left one. A TABLE CELL needs it enforced, or a long value runs straight
      // through its neighbour — "7-Machinery and Equipment(Production, Warehousing, Shipping)"
      // did exactly that, across the Asset Class column beside it, and only a rasterised page
      // showed it. `clip: true` says this box is the box.
      if (o.clip && o.w > 0) {
        const room = o.w - 2 * (o.pad === undefined ? 2.4 : o.pad);
        if (font.widthOfTextAtSize(s, size) > room) s = api.fit(s, size, o.bold, room);
        if (!s) return;
      }
      let tx;
      if (o.align === "r" || o.align === "right") tx = o.x + o.w - font.widthOfTextAtSize(s, size) - (o.pad === undefined ? 2.4 : o.pad);
      else if (o.align === "c" || o.align === "center" || o.align === "centre") tx = o.x + (o.w - font.widthOfTextAtSize(s, size)) / 2;
      else tx = o.x + (o.pad === undefined ? 2.4 : o.pad);
      page.drawText(s, { x: tx, y: o.y, size, font, color: colour(o.colour || INK.text) });
    },
    /** Text at an exact point — used for everything the template itself prints. */
    at(str, x, y, size, bold, colourOverride) {
      const s = winAnsi(str);
      if (!s) return;
      page.drawText(s, { x, y, size, font: bold ? fonts.bold : fonts.regular, color: colour(colourOverride || INK.text) });
    },
    rect(x, y, w, h, fill) { page.drawRectangle({ x, y, width: w, height: h, color: fill }); },
    box(o) {
      page.drawRectangle({
        x: o.x, y: o.y, width: o.w, height: o.h,
        color: o.fill ? colour(o.fill) : undefined,
        borderColor: o.border === false ? undefined : colour(INK.rule),
        borderWidth: o.border === false ? 0 : 0.5,
      });
    },
    outline(x, y, w, h) {
      page.drawRectangle({ x, y, width: w, height: h, borderColor: colour(INK.text), borderWidth: 0.5 });
    },
    /** A tick box and its label; returns the width consumed. */
    checkbox(o) {
      const s = 6.5;
      page.drawRectangle({ x: o.x, y: o.y, width: s, height: s, borderColor: colour(INK.text), borderWidth: 0.6 });
      if (o.on) {
        page.drawLine({ start: { x: o.x + 1.2, y: o.y + 3.2 }, end: { x: o.x + 2.7, y: o.y + 1.3 }, thickness: 1, color: colour(INK.text) });
        page.drawLine({ start: { x: o.x + 2.7, y: o.y + 1.3 }, end: { x: o.x + 5.4, y: o.y + 5.3 }, thickness: 1, color: colour(INK.text) });
      }
      api.text(o.label, { x: o.x + s + 1, y: o.y + 0.8, w: 200, size: SIZE.small, pad: 1 });
      return s + 3 + api.width(o.label, SIZE.small);
    },
    /**
     * A DocuSign anchor: real text, drawn in white, inside the cell it belongs to. DocuSign
     * finds the string and drops that recipient's tab there; nobody sees it.
     */
    anchor(str, o) {
      page.drawText(winAnsi(str), { x: o.x + 2, y: o.y, size: 6, font: fonts.regular, color: rgb(1, 1, 1) });
    },
  };
  return api;
}

const get = (obj, path) => String(path).split(".").reduce((o, k) => (o == null ? undefined : o[k]), obj);

// Where a single line of text sits in a box, matched to how Excel prints the same cell:
// vertically centred on the row, and inset from the cell edge by Excel's own two pixels at
// this print scale. Both were measured against the PDF Excel prints from the template.
const baselineIn = (box, size) => box[1] + (box[3] - size) / 2 + size * 0.14;
const CELL_PAD = 1.34;
// An accounting cell insets its currency mark a little further and its figure a little less;
// both measured off the template's own print.
const ACCT_PAD = { currency: 3.34, figure: 1.7 };

// ---- page 1 · the AFE Form sheet, as the template prints it ---------------------------------
function drawForm(cv, model, opts) {
  // 1. the rules and the tints, in the order Excel painted them
  for (const r of layout.RECTS) cv.rect(r.x, r.y, r.w, r.h, hex(r.c));

  // 2. the document control block above the grid. The footer is NOT drawn here: every page's
  // footer is drawn in one pass at the end, once the page count is settled. Drawing page 1's
  // early printed "Page 1 of 2" on a document that had gained a third page by the time page 2
  // was footed — two different totals in one PDF.
  for (const line of layout.DOC_HEADER) cv.at(line.t, line.x, line.y, line.s, false);

  // 3. the form's own printing, at the form's own coordinates
  for (const l of layout.LABELS) cv.at(l.t, l.x, l.y, l.s, !!l.b);

  // 4. what the tool fills in
  for (const slot of layout.SLOTS) drawSlot(cv, slot, model);

  // 5. the signing blocks
  drawSignBlocks(cv, model, opts);

  // 6. Fixed Assets' marks are NOT drawn here. They go onto the signed page itself, by
  // `markIssued` — the issued AFE is the signed file with those marks on it, never a fresh
  // drawing of the form (R156).
}

/**
 * The AuC number and the SAP budget table, where the FA team actually put them (R134).
 *
 * The worked example settles it: on `313469 BriCare AFE_FY-2026` the AuC number is written in red
 * in the top-left margin and the Budget / Actual / Commitments table is pasted into the top-right
 * one, both ABOVE the form's own grid, on page one. Ours put the same facts on page two, which
 * is tidier and is not what the reader is looking for: "the Issued by Fixed Assets and Budget /
 * Actual / Commitment are placed below rather than on top of the AFE form" (Shashank,
 * 2026-09-22).
 *
 * There is room for it, which is why this is safe. The template's own `DOC_HEADER` occupies
 * x 18-180 at y 779-787, and the grid starts at y 741 — so the band from x 190 to the right
 * margin, y 745 upwards, is empty on every AFE. Nothing is drawn over the form; nothing the
 * template prints is covered.
 *
 * And it CANNOT affect the form hash: `verifyFormHash` re-renders without `issued`, so these
 * marks exist on the issued copy only. `FORM_LAYOUT_VERSION` is unchanged for the same reason —
 * an AFE that has not been issued draws exactly what it drew before.
 */
function drawIssuedMarks(cv, model) {
  const iss = model.issued;
  if (!iss || !iss.ioNumber) return;
  const P = layout.PAGE;
  const RIGHT = P.width - 18;
  // The template's own furniture, measured rather than assumed: the grid starts here and the
  // document-control lines sit just above it on the left.
  const GRID = layout.RECTS.reduce((hi, r) => Math.max(hi, r.y + (r.h || 0)), 0);
  const HDR_TOP = 793, HDR_BOTTOM = 777;          // the two "Document Number / Name" lines

  // ---- the SAP table gets a BOX IT CANNOT LEAVE ------------------------------------------
  // "Ensure that the screenshot gets a designated boundary that it shouldn't cross — people take
  // SS in various ways." A tall narrow capture and a wide short one must both end up inside the
  // same rectangle, so the field block beside it never has to move and can never be covered.
  const SHOT = { x: 392, y: GRID + 2, w: RIGHT - 392, h: 834 - (GRID + 2) };
  let hasShot = false;
  const ev = iss.evidence;
  if (ev && ev.image) {
    const sc = Math.min(SHOT.w / ev.image.width, SHOT.h / ev.image.height, 1);
    const w = ev.image.width * sc, h = ev.image.height * sc;
    if (h >= 22 && w >= 70) {                      // below this it is not a readable table
      // Contained and pinned to the top-right of its box, the way it is pasted by hand.
      const x = SHOT.x + SHOT.w - w, y = SHOT.y + SHOT.h - h;
      cv.page.drawImage(ev.image, { x, y, width: w, height: h });
      cv.outline(x, y, w, h);
      hasShot = true;
      ev.onPageOne = true;
    } else {
      // A capture whose shape will not survive this box — a whole-window grab is 400×1200 and
      // comes out 27pt wide, a thin strip of just the total row comes out 14pt tall — gets a page
      // of its own at full size. It is never silently dropped: a screenshot the FA team attached
      // as proof, that then appears nowhere, is worse than one that takes an extra page.
      ev.overleaf = true;
    }
  }

  // ---- everything Fixed Assets recorded, in red, at the top ------------------------------
  // The AFE number is NOT here: it is printed red in the form's own AFE NO cell a few
  // millimetres below, and saying it twice wasted the room the rest of this needs.
  const fields = [
    ["AuC number", iss.aucNumber],
    ["Plant", iss.plant],
    ["Profit centre", iss.profitCentre],
    ["Order type", iss.orderType],
    ["Budget loaded (KO22)", iss.budgetLoaded],
    ["Issued", iss.issuedAt],
  ].filter((f) => f[1]);

  const left = 18;
  const right = hasShot ? SHOT.x - 8 : RIGHT;
  const LBL = 5.4, VAL = 7.4, ROW = 20;
  if (fields.length) {
    // The band ABOVE the document-control lines is free across the whole sheet, which is where
    // the AuC number is written by hand on the worked example. Two rows of three fit in it.
    const cols = Math.max(1, Math.min(3, Math.floor((right - left) / 108)));
    const rows = Math.ceil(fields.length / cols);
    const top = 834;
    if (top - rows * ROW >= HDR_TOP) {
      const cw = (right - left) / cols;
      fields.forEach((f, i) => {
        const r = Math.floor(i / cols), c = i % cols;
        const x = left + c * cw, yTop = top - r * ROW;
        cv.text(f[0].toUpperCase(), { x, y: yTop - LBL, w: cw - 6, size: LBL, bold: true, colour: INK.hint, clip: true });
        cv.text(String(f[1]), { x, y: yTop - LBL - VAL - 2, w: cw - 6, size: VAL, bold: true, colour: INK.red, clip: true });
      });
      cv.rect(left, top - rows * ROW + 1, right - left, 0.6, colour(INK.red));
    }
  }

  // ---- the note, in the strip below the document-control lines ---------------------------
  // Fixed Assets' own rate for SAP goes here too (R161), not into the band above: the band holds
  // six fields in two rows and drops whole past that, because a third row would not clear the
  // document-control lines. Who approved the issue LEADS it (R168), so that if a long note runs
  // out of strip it is the note that is shortened and never the name.
  const note = [String(iss.approvalText || "").trim(), String(iss.fxText || "").trim(), String(iss.note || "").trim()]
    .filter(Boolean).join(" · ");
  if (note) {
    const w = right - left;
    const lines = cv.wrap(`Fixed Assets: ${note}`, 6.4, false, w, 3);
    let y = HDR_BOTTOM - 6.4 - 1;
    for (const line of lines) {
      if (y < GRID + 2) break;                     // never into the form's own grid
      cv.text(line, { x: left, y, w, size: 6.4, colour: INK.red, clip: true });
      y -= 7.6;
    }
  }
}

function drawDocFooter(cv, pageNo, pageCount, landscape) {
  // The footer's coordinates come from the template's own portrait page. On a turned page the
  // right-hand box would land off the sheet, so the page number is placed against the landscape
  // width instead and the left-hand lines keep their offset from the bottom.
  const pageWidth = landscape ? PAGE.height : PAGE.width;
  const boxes = layout.DOC_FOOTER.boxes.filter((b) => b.s > 0);
  const left = (layout.DOC_FOOTER.lines.find((l) => l.side === "left") || { text: "" }).text
    .replace(/&[Kk]\d+\+\d+/g, "").split("\n");
  if (boxes[0] && left[0]) cv.at(left[0], boxes[0].x, boxes[0].y, boxes[0].s, false, INK.hint);
  const second = boxes[2] || boxes[1];
  if (second && left[1]) cv.at(left[1], second.x, second.y, second.s, false, INK.hint);
  const right = boxes.find((b) => b.x > PAGE.width / 2);
  if (right) {
    const text = `Page ${pageNo} of ${pageCount}`;
    const x = landscape ? pageWidth - extra.PAGE.marginX - 90 : right.x;
    const w = landscape ? 90 : PAGE.width - right.x - layout.COLS[0];
    cv.text(text, { x, y: right.y, w, size: right.s, align: "r", colour: INK.hint, pad: 0 });
  }
}

/** One value in its own box: the form's alignment, the form's number format. */
// Which of the form's OWN cells turn red on the issued copy. Only the AFE number: everything
// else on the grid was there when it was signed, and colouring a signed value would say Fixed
// Assets had changed it.
const RED_ON_ISSUED = ["header.afeNo"];
/** The cells that carry local currency (R161): the only ones set smaller to fit. */
const LOCAL_SLOT = /^money\.(fxRate|\w+Lc)$/;

function drawSlot(cv, slot, model) {
  const box = slot.box;
  const size = slot.size;
  if (slot.check) return drawCheck(cv, slot, model);

  let value = get(model, slot.key);
  if (value === undefined || value === null) value = "";
  value = String(value);

  if (slot.accounting) {
    // The form's money columns are accounting-formatted: the currency mark against the left
    // edge, the figure against the right, a bare dash for nothing. Keeping that is what makes
    // the columns line up the way the signed form does.
    const empty = value === "" || /^0(\.00)?$/.test(value.replace(/[$,\s]/g, ""));
    const figure = empty ? "-" : value.replace(/^\s*\$\s*/, "");
    const y = baselineIn(box, size);
    if (slot.currency) cv.at(slot.currency, box[0] + ACCT_PAD.currency, y, size, !!slot.b);
    // A local-currency figure is dollars times the rate, so a rupiah or a won runs to a dozen
    // digits in a 54pt box (R161). It is set smaller until it fits — never cut, never ellipsed,
    // because a number with its end missing is a different number. Only the local cells and the
    // rate: every dollar cell keeps the size it always drew at, so no signed page moves.
    let fs = size;
    if (!empty && LOCAL_SLOT.test(slot.key)) {
      const room = box[2] - ACCT_PAD.figure - 1;
      while (fs > 3.5 && cv.width(figure, fs, !!slot.b) > room) fs -= 0.25;
    }
    cv.text(figure, { x: box[0], y, w: box[2], size: fs, bold: !!slot.b, align: "r", pad: empty ? 8 : ACCT_PAD.figure });
    return;
  }

  if (!value) return;
  // The AFE number is the one value on the form's own grid that Fixed Assets writes AFTER the
  // signatures — SAP assigns it at KO01 and it is blank on everything the approvers saw. On the
  // issued copy it is red for the same reason every other post-signature mark is (R135).
  const red = model.issued && model.issued.ioNumber && RED_ON_ISSUED.includes(slot.key);
  if (slot.wrap) {
    const maxLines = Math.max(1, Math.floor(box[3] / (size + 1.2)));
    const lines = cv.wrap(value, size, !!slot.b, box[2] - 4.8, maxLines);
    let y = lines.length === 1 ? baselineIn(box, size) : box[1] + box[3] - size;
    for (const line of lines) {
      cv.text(line, { x: box[0], y, w: box[2], size, bold: !!slot.b || red, align: slot.align, pad: CELL_PAD, colour: red ? INK.red : undefined });
      y -= size + 1.2;
    }
    return;
  }
  cv.text(value, { x: box[0], y: baselineIn(box, size), w: box[2], size, bold: !!slot.b || red, align: slot.align, pad: CELL_PAD, colour: red ? INK.red : undefined });
}

/**
 * The Yes/No pair beside a question. Excel's own print shows the two captions and no box —
 * the tick lives in a form control that does not export — so the captions are printed exactly
 * where the form puts them and the answer is ringed. That ring is the one mark on this page
 * that the template does not itself draw.
 */
function drawCheck(cv, slot, model) {
  const value = get(model, slot.key);
  // formModel gives a check as the form's own options with one of them on.
  const picked = Array.isArray(value) ? (value.find((o) => o.on) || {}).value || (value.find((o) => o.on) || {}).label : value;
  const chosen = picked === true || /^(y|yes|true)$/i.test(String(picked || "")) ? "yes"
    : picked === false || /^(n|no|false)$/i.test(String(picked || "")) ? "no" : null;
  if (!chosen) return;
  const cap = slot.check[chosen];
  if (!cap) return;
  const w = cv.width(chosen === "yes" ? "Yes" : "No", cap.s, false);
  cv.outline(cap.x - 1.6, cap.y - 1.3, w + 3.2, cap.s + 2.4);
}

// ---- the signing blocks ---------------------------------------------------------------------
function drawSignBlocks(cv, model, opts) {
  const seatInto = (geom, seat, note) => {
    if (!geom) return;
    const name = geom.name.box;
    if (seat) {
      cv.text(seat.name, { x: name[0], y: baselineIn(name, geom.name.size) + (seat.group ? 3.2 : 0), w: name[2], size: geom.name.size, align: "center" });
      if (seat.group) {
        cv.text(seat.group, { x: name[0], y: baselineIn(name, geom.name.size) - 4.4, w: name[2], size: geom.name.size - 1.4, align: "center", colour: INK.hint });
      }
      const sig = geom.signature.box, date = geom.date.box;
      if (seat.anchor) {
        cv.anchor(seat.anchor.sig, { x: sig[0], y: baselineIn(sig, 6) });
        cv.anchor(seat.anchor.date, { x: date[0], y: baselineIn(date, 6) });
      }
      // A completed envelope's copy shows what was signed, and when.
      if (opts.stamped && seat.status === "signed") {
        cv.text(seat.name, { x: sig[0], y: baselineIn(sig, geom.signature.size) + 2, w: sig[2], size: geom.signature.size + 1, align: "center" });
        cv.text("signed electronically", { x: sig[0], y: baselineIn(sig, geom.signature.size) - 4.4, w: sig[2], size: geom.signature.size - 2, align: "center", colour: INK.hint });
        cv.text(formDate(seat.signedAt), { x: date[0], y: baselineIn(date, geom.date.size), w: date[2], size: geom.date.size - 0.8, align: "center" });
      }
    } else if (note) {
      cv.text(note, { x: name[0], y: baselineIn(name, geom.name.size - 1), w: name[2], size: geom.name.size - 1, align: "center", colour: INK.hint });
    }
  };

  // Controllership Review — above $1M the form asks for a partner's signature (R57).
  const partner = model.approvals.controllership[0] || null;
  const ctrl = {
    name: { box: slotBox("controllership.name"), size: slotSize("controllership.name"), align: "center" },
    signature: { box: slotBox("controllership.signature"), size: slotSize("controllership.signature"), align: "center" },
    date: { box: slotBox("controllership.date"), size: slotSize("controllership.date"), align: "center" },
  };
  seatInto(ctrl, partner, partner ? null : "not required for this value");

  model.approvals.projectApprovals.forEach((seat, i) => {
    seatInto(layout.PROJECT_APPROVALS[i], seat, null);
  });
  model.approvals.financialApprovals.forEach((row, i) => {
    seatInto(layout.FINANCIAL_APPROVALS[i], row.seat, row.note);
  });
}

const slotOf = (key) => layout.SLOTS.find((s) => s.key === key) || { box: [0, 0, 0, 0], size: 7.32 };
const slotBox = (key) => slotOf(key).box;
const slotSize = (key) => slotOf(key).size;

// ---- the pages after the form ----------------------------------------------------------------
function pageTitle(cv, text) {
  let y = PAGE.height - extra.PAGE.marginTop;
  y -= 20;
  cv.box({ x: extra.x(0), y, w: extra.w(0, 7), h: 20, fill: INK.head });
  cv.text(text, { x: extra.x(0), y: y + 6, w: extra.w(0, 7), size: SIZE.title, bold: true, align: "c" });
  return y;
}

/** Signers the form's own rows cannot hold — a coordinator's additions beyond fourteen. */
function drawOverflow(cv, model, opts) {
  let y = pageTitle(cv, "Additional Approvals");
  const cols = [{ c: 0, span: 2, label: "Role" }, { c: 2, span: 2, label: "Approver Name" }, { c: 4, span: 2, label: "Signature" }, { c: 6, span: 1, label: "Date" }];
  y -= 16;
  for (const col of cols) {
    cv.box({ x: extra.x(col.c), y, w: extra.w(col.c, col.span), h: 16, fill: INK.head });
    cv.text(col.label, { x: extra.x(col.c), y: y + 4.6, w: extra.w(col.c, col.span), size: SIZE.head, bold: true, align: col.c === 0 ? "l" : "c" });
  }
  for (const seat of model.approvals.overflow) {
    y -= 26;
    for (const col of cols) cv.box({ x: extra.x(col.c), y, w: extra.w(col.c, col.span), h: 26 });
    cv.text(seat.level || seat.role || "", { x: extra.x(0), y: y + 11, w: extra.w(0, 2), size: SIZE.small });
    cv.text(seat.name, { x: extra.x(2), y: y + 11, w: extra.w(2, 2), size: SIZE.value, align: "c" });
    if (seat.anchor) {
      cv.anchor(seat.anchor.sig, { x: extra.x(4), y: y + 10 });
      cv.anchor(seat.anchor.date, { x: extra.x(6), y: y + 10 });
    }
    if (opts.stamped && seat.status === "signed") {
      cv.text(seat.name, { x: extra.x(4), y: y + 12, w: extra.w(4, 2), size: 8, align: "c" });
      cv.text("signed electronically", { x: extra.x(4), y: y + 4, w: extra.w(4, 2), size: 5.4, align: "c", colour: INK.hint });
      cv.text(formDate(seat.signedAt), { x: extra.x(6), y: y + 12, w: extra.w(6, 1), size: SIZE.small, align: "c" });
    }
  }
  cv.text("These signers are beyond the fourteen rows the form prints; they were added for this AFE and are part of the same envelope.",
    { x: extra.x(0), y: y - 16, w: extra.w(0, 7), size: SIZE.note, colour: INK.hint });
}

function drawProjectDetails(cv, model) {
  let y = pageTitle(cv, "Project Details");
  for (const field of extra.PROJECT_DETAILS) {
    // A row that does not apply is not printed as an empty box: the 925 surplus question only
    // belongs on an AFE that buys something physical, and a blank row on a signed form reads
    // as an unanswered question rather than an inapplicable one.
    if (field.when && !get(model, field.when)) continue;
    y -= field.h;
    const lx = extra.x(0), lw = extra.w(0, 2);
    const vx = extra.x(2), vw = extra.w(2, 5);
    cv.box({ x: lx, y, w: lw, h: field.h, fill: INK.band });
    cv.box({ x: vx, y, w: vw, h: field.h });
    const labelLines = cv.wrap(field.label, SIZE.label, true, lw - 7, 3);
    let ly = y + field.h - SIZE.label - 3;
    for (const line of labelLines) { cv.text(line, { x: lx, y: ly, w: lw, size: SIZE.label, bold: true }); ly -= SIZE.label + 1.6; }
    if (field.hint) cv.text(field.hint, { x: lx, y: y + 3, w: lw, size: 5.4, colour: INK.hint });
    const value = get(model, field.v) || "";
    const lines = cv.wrap(value, SIZE.value, false, vw - 8, Math.max(1, Math.floor((field.h - 4) / (SIZE.value + 2))));
    let vy = y + field.h - SIZE.value - 3.5;
    for (const line of lines) { cv.text(line, { x: vx, y: vy, w: vw, size: SIZE.value }); vy -= SIZE.value + 2; }
  }

  // The bottom of this page was a hand's width of white (the screenshot at Meeting #5, 68:00).
  // Three blocks now use it, each printed only when it has something to say.
  y = drawExceptions(cv, model, y - 18);
  drawDocuments(cv, model, y - 16);
  // The Issued block used to print here, and it does not any more (R137). Everything Fixed
  // Assets records is at the TOP of page one now — "whatever the FA team adds must be visible
  // immediately to any recipient in the first look, no scroll needed" — so repeating it down
  // here is the same facts twice, and the second copy is the one nobody reads. It also ran
  // into the document footer, which is what made the duplication visible.
}

/** A small heading rule, shared by the three blocks below. */
function blockHeading(cv, text, y, sub) {
  cv.text(text, { x: extra.x(0), y, w: extra.w(0, 7), size: SIZE.head, bold: true });
  let next = y - (SIZE.head + 3);
  if (sub) {
    const lines = cv.wrap(sub, SIZE.note, false, extra.w(0, 7), 2);
    for (const line of lines) { cv.text(line, { x: extra.x(0), y: next, w: extra.w(0, 7), size: SIZE.note, colour: INK.hint }); next -= SIZE.note + 1.4; }
    next -= 2;
  }
  return next;
}

/**
 * A check that did not pass, and the reason it was accepted anyway.
 *
 * This is the block Euan described at 24:46 — an approver who meets an exception either sends
 * it back or opens a conversation, and the requester's own words save them both. It prints on
 * the form the approvers actually sign, not just on the screen, because DocuSign is where most
 * of them will read it.
 */
function drawExceptions(cv, model, top) {
  const rows = model.exceptions || [];
  if (!rows.length) return top;
  const spec = extra.EXCEPTIONS_BLOCK;
  let y = blockHeading(cv, spec.title, top, spec.intro);
  for (const row of rows) {
    const noteLines = cv.wrap(row.note || "", SIZE.value, false, extra.w(0, 7) - 14, 3);
    const h = Math.max(spec.rowHeight, 13 + noteLines.length * (SIZE.value + 2));
    y -= h;
    cv.box({ x: extra.x(0), y, w: extra.w(0, 7), h, fill: INK.warm });
    cv.text(row.label || "", { x: extra.x(0) + 5, y: y + h - SIZE.small - 3.5, w: extra.w(0, 7) - 10, size: SIZE.small, bold: true });
    let ny = y + h - SIZE.small - SIZE.value - 6;
    for (const line of noteLines) { cv.text(line, { x: extra.x(0) + 5, y: ny, w: extra.w(0, 7) - 10, size: SIZE.value }); ny -= SIZE.value + 2; }
    const who = [row.by, row.at].filter(Boolean).join(" · ");
    if (who) cv.text(who, { x: extra.x(0) + 5, y: y + 3, w: extra.w(0, 7) - 10, size: 5.4, colour: INK.hint });
  }
  return y;
}

/**
 * What came with the AFE, and where each piece actually is.
 *
 * Imogen wanted everything in one PDF (67:54) and Shashank's answer was that some of it will not
 * fit: a sixty-page facilities pack or a spreadsheet does not belong inside a signed form, and
 * pasting it in is how the Banjo AFE ended up with a screenshot cut off at the margin. So the
 * pack merges what merges cleanly and LISTS the rest with a link — a reader always knows the
 * whole set, and never sees half a document.
 */
function drawDocuments(cv, model, top) {
  const rows = (model.documents || []).filter((d) => d.role !== "issued_pack");
  if (!rows.length) return top;
  const spec = extra.DOCUMENTS_BLOCK;
  let y = blockHeading(cv, spec.title, top);
  const totalChars = spec.columns.reduce((a, c) => a + c.chars, 0);
  const unit = extra.w(0, 7) / totalChars;
  const colX = [];
  let cx = extra.x(0);
  for (const c of spec.columns) { colX.push(cx); cx += c.chars * unit; }

  y -= spec.rowHeight;
  cv.box({ x: extra.x(0), y, w: extra.w(0, 7), h: spec.rowHeight, fill: INK.head });
  spec.columns.forEach((c, i) => cv.text(c.label, { x: colX[i] + 4, y: y + 4.5, w: c.chars * unit - 6, size: SIZE.small, bold: true }));

  for (const d of rows) {
    y -= spec.rowHeight;
    cv.box({ x: extra.x(0), y, w: extra.w(0, 7), h: spec.rowHeight });
    // "In the AFE record" was printed for the KO22 screenshot while it was drawn four lines
    // below, on the same page. The Documents table exists so a reader always knows where every
    // piece is; being wrong about the one thing printed beside it is the worst case.
    // The one the caller says is drawn — not every screenshot of the right role. Only ONE fits
    // in the box at the top of page one, and a second one attached is an ordinary attachment.
    const drawnHere = Boolean(d.drawn) && model.issued && model.issued.evidence;
    const where = d.merged ? "Bound into this PDF"
      // "Printed in this PDF" rather than a page number: the table is either in the box at the
      // top of page one or on a page of its own, and which of the two depends on the shape of
      // the capture. Both are true of this phrasing.
      : drawnHere ? "Printed in this PDF"
      : (model.issued && model.issued.ioNumber ? "In the AFE record" : "Attached to this AFE");
    const values = { filename: d.filename, roleLabel: d.roleLabel, size: d.size, where };
    spec.columns.forEach((c, i) => {
      const text = cv.wrap(String(values[c.key] || ""), SIZE.value, false, c.chars * unit - 8, 1)[0] || "";
      cv.text(text, { x: colX[i] + 4, y: y + 4.5, w: c.chars * unit - 8, size: SIZE.value });
    });
  }

  // On the issued copy, say where "in the AFE record" actually is. A URL does not fit in a
  // 29-character column, and it is the same address for every row, so it belongs under the
  // table. It is absolute wherever PUBLIC_URL is set, because whoever reads this PDF is
  // reading it in their mail client, not in the application.
  const link = model.issued && model.issued.link;
  if (link && rows.some((d) => !d.merged) && /^https?:/i.test(link)) {
    y -= SIZE.note + 5;
    cv.text(`Everything not bound into this PDF is on the AFE at ${link}`,
      { x: extra.x(0), y, w: extra.w(0, 7), size: SIZE.note, colour: INK.hint });
  }
  return y;
}

/**
 * The evidence image with its caption, at `top`, in at most `maxHeight` points. Returns the new
 * y, or null when it will not fit in the space offered — a caller that gets null gives it a page.
 */
function drawEvidence(cv, image, spec, top, maxHeight, opts) {
  if (!(maxHeight > 60)) return null;                        // less than this is not a readable table
  const maxW = extra.w(0, 7);
  const scale = Math.min(maxW / image.width, maxHeight / image.height, 1);
  const w = image.width * scale, h = image.height * scale;
  let y = top - 12;
  if (!opts || opts.caption !== false) {
    cv.text(spec.caption, { x: extra.x(0), y, w: maxW, size: SIZE.small, bold: true, colour: INK.red });
  }
  y -= h + 4;
  cv.page.drawImage(image, { x: extra.x(0), y, width: w, height: h });
  cv.outline(extra.x(0), y, w, h);
  return y;
}

/** The evidence on a page of its own, when its shape will not survive the box on page one. */
function drawEvidencePage(cv, model) {
  const spec = extra.EVIDENCE_PAGE;
  const y = pageTitle(cv, spec.caption);
  cv.text("Attached by Fixed Assets after KO22. It is the proof that internal order "
    + `${(model.issued && model.issued.ioNumber) || ""} exists and that its budget is unlocked.`,
    { x: extra.x(0), y: y - 12, w: extra.w(0, 7), size: SIZE.note, colour: INK.hint });
  drawEvidence(cv, model.issued.evidence.image, spec, y - 12, y - 24 - extra.PAGE.marginBottom - 20, { caption: false });
}

/**
 * The financial case across eleven years (R94), landscape.
 *
 * The rows are the spreadsheet's own and in its order; `lib/domain/financials.js` carries the
 * arithmetic and names the sheet's row numbers beside each step. Everything below TOTAL CASH
 * OUTFLOWS is computed, which is what the sheet means by its "Red Text Denotes Calculated
 * Field" note — here the whole lower half is.
 */
function drawFinancials(cv, model) {
  const spec = extra.FINANCIALS_PAGE;
  const f = model.financials;
  if (!f) return;
  const W = PAGE.height;                                   // landscape: the long edge is across
  const left = extra.PAGE.marginX;
  const right = W - extra.PAGE.marginX;
  const width = right - left;

  let y = PAGE.width - extra.PAGE.marginTop - 20;
  cv.box({ x: left, y, w: width, h: 20, fill: INK.head });
  cv.text(spec.title, { x: left, y: y + 6, w: width, size: SIZE.title, bold: true, align: "c" });
  y -= 13;
  cv.text(spec.note, { x: left, y, w: width, size: SIZE.note, colour: INK.hint });

  // One column per year, plus the label column on the left.
  const labelW = width * 0.26;
  const colW = (width - labelW) / f.years.length;
  const cell = (n) => (n === null || n === undefined ? "" : money2(n));

  y -= 16;
  cv.box({ x: left, y, w: labelW, h: 14, fill: INK.head });
  cv.text("ALL AMOUNTS IN USD", { x: left + 3, y: y + 4, w: labelW - 6, size: SIZE.small, bold: true });
  f.years.forEach((yr, n) => {
    const x = left + labelW + n * colW;
    cv.box({ x, y, w: colW, h: 14, fill: INK.head });
    cv.text(String(yr), { x, y: y + 4, w: colW, size: SIZE.head, bold: true, align: "r" });
  });

  const line = (label, values, opts) => {
    const o = opts || {};
    y -= spec.rowHeight;
    cv.box({ x: left, y, w: labelW, h: spec.rowHeight, fill: o.band ? INK.band : o.section ? INK.head : undefined });
    cv.text(label, { x: left + 3, y: y + 3.6, w: labelW - 6, size: SIZE.value, bold: Boolean(o.bold || o.section), clip: true });
    if (!values) {
      // A section heading: rule the row across so the band reads as one.
      f.years.forEach((_, n) => cv.box({ x: left + labelW + n * colW, y, w: colW, h: spec.rowHeight, fill: o.section ? INK.head : undefined }));
      return;
    }
    values.forEach((v, n) => {
      const x = left + labelW + n * colW;
      cv.box({ x, y, w: colW, h: spec.rowHeight, fill: o.band ? INK.band : undefined });
      cv.text(cell(v), { x, y: y + 3.6, w: colW, size: SIZE.value, bold: Boolean(o.bold), align: "r" });
    });
  };

  for (const row of spec.rows) {
    if (row.section) { line(row.label, null, { section: true }); continue; }
    if (row.detail) {
      // The rows a person typed, by their own descriptions. An empty one is not printed: the
      // template's ten blank rows are exactly what makes its own arithmetic fail.
      for (const r of (model.financialsInput && model.financialsInput[row.key]) || []) {
        const amounts = (r.amounts || []).slice(0, f.years.length);
        if (!amounts.some((a) => Number(a))) continue;
        line(r.description || "—", f.years.map((_, n) => Number(amounts[n]) || 0), {});
      }
      continue;
    }
    let label = row.label;
    if (row.pctOfPolicy) label += ` : ${Math.round(f.policy[row.pctOfPolicy] * 100)}%`;
    if (row.ratePolicy) label += ` at ${Math.round(f.policy[row.ratePolicy] * 100)}%`;
    line(label, f[row.key], { bold: row.bold, band: row.band });
  }

  // The four figures a reader looks for first, along the bottom.
  y -= 26;
  const boxW = width / spec.summary.length;
  spec.summary.forEach((item, n) => {
    const x = left + n * boxW;
    cv.box({ x, y, w: boxW, h: 26, fill: INK.band });
    cv.text(item.label, { x: x + 4, y: y + 16, w: boxW - 8, size: SIZE.small, bold: true });
    const v = f[item.key];
    const text = v === null || v === undefined ? "not calculable"
      : item.money ? money2(v)
      : item.pct ? `${v}%`
      : item.key === "payback" && !f.paybackWithin ? `beyond ${f.years.length - 1}`
      : String(v);
    cv.text(text, { x: x + 4, y: y + 4, w: boxW - 8, size: SIZE.title, bold: true });
  });
}

/**
 * The Asset Acquisition block and the schedule behind it (R96, R97), landscape.
 *
 * The block a real signed AFE prints `#DIV/0!` and `Jan-00` into when the life is left blank.
 * Neither is reachable here — the life is required before the AFE can be sent.
 */
function drawAssets(cv, model) {
  const spec = extra.ASSET_PAGE;
  const f = model.financials;
  if (!f || !f.assets.length) return;
  const W = PAGE.height;
  const left = extra.PAGE.marginX;
  const width = W - 2 * extra.PAGE.marginX;

  let y = PAGE.width - extra.PAGE.marginTop - 20;
  cv.box({ x: left, y, w: width, h: 20, fill: INK.head });
  cv.text(spec.title, { x: left, y: y + 6, w: width, size: SIZE.title, bold: true, align: "c" });
  y -= 13;
  cv.text(spec.note, { x: left, y, w: width, size: SIZE.note, colour: INK.hint });

  const table = (columns, rows, top) => {
    const unit = width / columns.reduce((a, c) => a + c.chars, 0);
    let x = left;
    const xs = columns.map((col) => { const at = { x, w: col.chars * unit, col }; x += at.w; return at; });
    let ty = top - 16;
    for (const c of xs) {
      cv.box({ x: c.x, y: ty, w: c.w, h: 16, fill: INK.head });
      cv.text(c.col.label, { x: c.x, y: ty + 4.6, w: c.w, size: SIZE.head, bold: true, align: c.col.align, clip: true });
    }
    for (const row of rows) {
      ty -= spec.rowHeight;
      for (const c of xs) {
        cv.box({ x: c.x, y: ty, w: c.w, h: spec.rowHeight });
        cv.text(row[c.col.key] === null || row[c.col.key] === undefined ? "" : String(row[c.col.key]),
          { x: c.x, y: ty + 4.2, w: c.w, size: SIZE.value, align: c.col.align, clip: true });
      }
    }
    return ty;
  };

  y = table(spec.columns, f.assets.map((a) => ({
    description: a.description,
    cost: money2(a.costUsd),
    life: a.lifeYears === null ? "" : String(a.lifeYears),
    inService: formDate(a.inServiceDate),
    eol: formDate(a.endOfLife),
    annual: a.annualDepreciation === null ? "" : money2(a.annualDepreciation),
    assetLife: a.assetLife || "",
    assetClass: a.assetClass || "",
  })), y - 6);

  // The schedule: one row per asset, one column per year, then the total the tax line uses.
  y -= 22;
  cv.text(spec.scheduleTitle, { x: left, y, w: width, size: SIZE.head, bold: true });
  const labelW = width * 0.26;
  const colW = (width - labelW) / f.years.length;
  y -= 16;
  cv.box({ x: left, y, w: labelW, h: 14, fill: INK.head });
  f.years.forEach((yr, n) => {
    const x = left + labelW + n * colW;
    cv.box({ x, y, w: colW, h: 14, fill: INK.head });
    cv.text(String(yr), { x, y: y + 4, w: colW, size: SIZE.head, bold: true, align: "r" });
  });
  const scheduleRow = (label, values, bold) => {
    y -= spec.rowHeight;
    cv.box({ x: left, y, w: labelW, h: spec.rowHeight, fill: bold ? INK.band : undefined });
    cv.text(label, { x: left + 3, y: y + 4, w: labelW - 6, size: SIZE.value, bold: Boolean(bold), clip: true });
    values.forEach((v, n) => {
      const x = left + labelW + n * colW;
      cv.box({ x, y, w: colW, h: spec.rowHeight, fill: bold ? INK.band : undefined });
      cv.text(v ? money2(v) : "", { x, y: y + 4, w: colW, size: SIZE.value, bold: Boolean(bold), align: "r" });
    });
  };
  for (const a of f.assets) scheduleRow(a.description || "—", a.byYear, false);
  scheduleRow("Total Depreciation/Amortization", f.depreciation, true);

  // Cost centre mapping, where the sheet keeps it (row 111).
  const mapping = (model.financialsInput && model.financialsInput.costCentreRows) || [];
  if (mapping.length) {
    y -= 22;
    cv.text(spec.costCentreTitle, { x: left, y, w: width, size: SIZE.head, bold: true });
    table(spec.costCentreColumns, mapping.map((r) => ({
      description: r.description || "",
      budgetUsd: r.budgetUsd === null || r.budgetUsd === undefined ? "" : money2(r.budgetUsd),
      budgetLocal: r.budgetLocal || "",
      costCentre: r.costCentre || "",
      owner: r.owner || "",
      legalEntity: r.legalEntity || "",
    })), y - 6);
  }
}

function drawLines(cv, model) {
  const spec = extra.LINES_PAGE;
  const totalChars = spec.columns.reduce((a, c) => a + c.chars, 0);
  const unit = extra.w(0, 7) / totalChars;
  let y = pageTitle(cv, spec.title);
  y -= 14;
  cv.text(spec.note, { x: extra.x(0), y: y + 3, w: extra.w(0, 7), size: SIZE.note, colour: INK.hint });

  const xs = [];
  let cx = extra.x(0);
  for (const col of spec.columns) { xs.push({ x: cx, w: col.chars * unit, col }); cx += col.chars * unit; }
  y -= 16;
  for (const c of xs) {
    cv.box({ x: c.x, y, w: c.w, h: 16, fill: INK.head });
    cv.text(c.col.label, { x: c.x, y: y + 4.6, w: c.w, size: SIZE.head, bold: true, align: c.col.align });
  }
  for (const row of model.lines.rows) {
    y -= 15;
    for (const c of xs) {
      cv.box({ x: c.x, y, w: c.w, h: 15 });
      cv.text(row[c.col.key] || "", { x: c.x, y: y + 4.2, w: c.w, size: SIZE.value, align: c.col.align });
    }
  }
  y -= 16;
  for (const c of xs) {
    cv.box({ x: c.x, y, w: c.w, h: 16, fill: INK.band });
    if (c.col.key === "site") cv.text("Total", { x: c.x, y: y + 4.6, w: c.w, size: SIZE.head, bold: true });
    if (c.col.key === "amountUsd") cv.text(model.lines.totalUsd, { x: c.x, y: y + 4.6, w: c.w, size: SIZE.head, bold: true, align: "r" });
  }
}

function drawCloud(cv, model) {
  const spec = extra.CLOUD_PAGE;
  const full = extra.w(0, 7);
  let y = pageTitle(cv, spec.title);

  const introLines = cv.wrap(spec.intro, SIZE.value, true, full - 20, 4);
  y -= introLines.length * (SIZE.value + 3) + 10;
  let iy = y + introLines.length * (SIZE.value + 3) + 2;
  for (const line of introLines) { cv.text(line, { x: extra.x(0), y: iy, w: full, size: SIZE.value, bold: true, align: "c" }); iy -= SIZE.value + 3; }

  const qw = extra.w(0, 4), ow = extra.w(4, 3);
  for (const q of model.cloud.questions) {
    const lines = cv.wrap(`${q.n}: ${q.q}`, SIZE.value, false, qw - 8, 4);
    const h = Math.max(30, lines.length * (SIZE.value + 2) + 10);
    y -= h;
    cv.box({ x: extra.x(0), y, w: qw, h });
    cv.box({ x: extra.x(4), y, w: ow, h });
    let ly = y + h - SIZE.value - 4;
    for (const line of lines) { cv.text(line, { x: extra.x(0), y: ly, w: qw, size: SIZE.value }); ly -= SIZE.value + 2; }
    let oy = y + h - 12;
    for (const opt of q.options) { cv.checkbox({ x: extra.x(4) + 6, y: oy, label: opt.label, on: opt.on }); oy -= 12; }
  }

  y -= 8;
  const cLines = cv.wrap(spec.conclusion, SIZE.value, false, full - 10, 3);
  const ch = cLines.length * (SIZE.value + 2) + 8;
  y -= ch;
  cv.box({ x: extra.x(0), y, w: full, h: ch, fill: INK.band });
  let cy = y + ch - SIZE.value - 3;
  for (const line of cLines) { cv.text(line, { x: extra.x(0), y: cy, w: full, size: SIZE.value }); cy -= SIZE.value + 2; }

  if (model.cloud.outcome) {
    y -= 22;
    const verdict = model.cloud.outcome === "cloud_capex" ? "These answers reach Cloud CapEx (CCA)."
      : model.cloud.outcome === "regular_capex" ? "These answers do not reach Cloud CapEx — this is regular CapEx."
        : "The Cloud CapEx questions do not apply to this AFE.";
    cv.text(verdict + (model.cloud.fpaReviewRequired ? " The FP&A Business Partner must review it." : ""),
      { x: extra.x(0), y: y + 6, w: full, size: SIZE.value, bold: true });
  }
}

// ---- the document ------------------------------------------------------------------------------
/**
 * @param {object} afe
 * @param {object} routing   frozen routing, or the live preview before send
 * @param {object} opts      { stamped: true } draws the signatures on a completed copy
 * @returns {Promise<{bytes: Buffer, formHash: string, pages: number, model: object, anchors: Array}>}
 */
async function renderAfeForm(afe, routing, opts) {
  const options = opts || {};
  // `validation`, `issued` and `documentsMerged` reach the model from here: the Exceptions
  // block, the Fixed Assets block and the Documents page are all things the caller knows and
  // the AFE alone does not.
  const model = buildFormModel(afe, routing, options);
  const doc = await PDFDocument.create({ updateMetadata: false });
  doc.registerFontkit(fontkit);
  // Embedded whole, deliberately: pdf-lib's subsetter mis-writes this font and drops most of
  // its outlines. tools/build_form_font.py already cut it to what the form can print, so the
  // vendored file is the subset.
  const fonts = {
    regular: await doc.embedFont(FONT_BYTES.regular, { subset: false }),
    bold: await doc.embedFont(FONT_BYTES.bold, { subset: false }),
  };
  const cv = makeCanvas(doc, fonts);

  // The KO22 evidence, embedded once so the issued block can draw it (R103, R104). The caller
  // hands over the raw bytes and their type; pdf-lib takes PNG and JPEG natively, and anything
  // it will not open is left out rather than allowed to fail the whole render — by then the
  // order exists in SAP and a picture must not be able to undo that.
  if (model.issued && options.issued && options.issued.evidenceBytes) {
    try {
      const type = options.issued.evidenceType || "";
      const image = type === "image/png" ? await doc.embedPng(options.issued.evidenceBytes)
        : /^image\/jpe?g$/.test(type) ? await doc.embedJpg(options.issued.evidenceBytes)
        : null;
      if (image) model.issued.evidence = { image };
    } catch (e) { /* listed as a document instead; the pack still builds */ }
  }

  // Each entry is a page. A `landscape` flag turns the sheet: eleven years of figures do not
  // fit across a portrait A4 at 7pt (R94).
  const pages = [{ draw: () => drawForm(cv, model, options) }];
  if (model.approvals.overflow.length) pages.push({ draw: () => drawOverflow(cv, model, options) });
  pages.push({ draw: () => drawProjectDetails(cv, model) });
  if (model.lines.any) pages.push({ draw: () => drawLines(cv, model) });
  if (model.financials) {
    pages.push({ draw: () => drawFinancials(cv, model), landscape: true });
    if (model.financials.assets.length) pages.push({ draw: () => drawAssets(cv, model), landscape: true });
  }
  if (model.cloud.print) pages.push({ draw: () => drawCloud(cv, model) });

  const title = model.header.title || "AFE";
  const drawn = [];
  for (let i = 0; i < pages.length; i++) {
    if (pages[i].landscape) cv.newLandscapePage(); else cv.newPage();
    drawn.push({ page: cv.page, landscape: Boolean(pages[i].landscape) });
    pages[i].draw();
    // The SAP table has a box of its own at the top of page one and is contained inside it, so
    // there is no longer a case where it did not fit and needed a page to itself. If it is too
    // small to read at that size it is not drawn at all, and the Documents page still lists it.
    if (model.issued && model.issued.evidence && model.issued.evidence.overleaf) {
      model.issued.evidence.overleaf = false;
      pages.splice(i + 1, 0, { draw: () => drawEvidencePage(cv, model) });
    }
  }
  // Now that the count is settled, and not before. Every page, including the first. A landscape
  // page's footer sits at the same place on ITS page, which is a different place on the sheet.
  for (let i = 0; i < drawn.length; i++) {
    drawDocFooter(cv.usePage(drawn[i].page), i + 1, drawn.length, drawn[i].landscape);
  }

  doc.setTitle(`AFE — ${title}`);
  doc.setSubject(`Authority for Expenditure · cost centre ${model.header.costCenter || ""}`);
  doc.setProducer("AFE Workbench");
  doc.setCreator("AFE Workbench");
  doc.setCreationDate(DOC_DATE);
  doc.setModificationDate(DOC_DATE);

  const bytes = Buffer.from(await doc.save({ useObjectStreams: false }));
  const anchors = [];
  for (const seat of model.approvals.projectApprovals.concat(
    model.approvals.financialApprovals.map((r) => r.seat), model.approvals.controllership, model.approvals.overflow)) {
    if (seat && seat.anchor) anchors.push({ recipientId: seat.id, name: seat.name, n: seat.anchor.n, sig: seat.anchor.sig, date: seat.anchor.date });
  }
  anchors.sort((a, b) => a.n - b.n);
  return { bytes, formHash: crypto.createHash("sha256").update(bytes).digest("hex"), pages: pages.length, model, anchors };
}

/**
 * Fixed Assets' marks, drawn onto page one of a document that ALREADY EXISTS (R156).
 *
 * The issued AFE used to be `renderAfeForm({ issued })`: a fresh drawing of the form from the
 * AFE as it stands NOW, with the tool's own simulation of the signatures on it. So the document
 * the requester keeps was one nobody signed — an edit made during a Fixed Assets return that let
 * the signatures stand showed in it, a change to the layout between signing and issue redrew
 * it, and on a live envelope DocuSign's signatures would have been replaced by pictures the tool
 * drew. "The only change can come at FA review stage where red lines are added and more
 * documents can be appended … post FA finalization also, the document remains untampered"
 * (Shashank, 2026-09-22).
 *
 * So this draws the marks and nothing else — the red band at the top, the SAP table in its box,
 * the order number in the AFE NO cell that was blank on everything the approvers saw — onto the
 * signed page, whose own content is left exactly as it came. pdf-lib wraps a page's existing
 * content in a saved graphics state before drawing on it, so nothing a signing service left in
 * that state can move or recolour the marks.
 *
 * The coordinates are the layout's, which is generated from the template and has not moved page
 * one since it was first generated: every FORM_LAYOUT_VERSION so far has been a change to the
 * pages AFTER it. Regenerating the layout from a new template is the one change that would need
 * this to know which generation the signed page was drawn by (`envelope.formLayoutVersion`).
 *
 * @returns {{ evidence: null|{onPageOne, overleaf}, addEvidencePage: null|function }}
 */
async function markIssued(doc, page, afe, routing, issued) {
  doc.registerFontkit(fontkit);
  const fonts = {
    regular: await doc.embedFont(FONT_BYTES.regular, { subset: false }),
    bold: await doc.embedFont(FONT_BYTES.bold, { subset: false }),
  };
  const cv = makeCanvas(doc, fonts).usePage(page);
  const model = buildFormModel(afe, routing, { issued });
  // The number goes where the form says it goes, whatever the AFE record held when this was built.
  if (model.header && issued && issued.ioNumber) model.header.afeNo = issued.ioNumber;
  if (issued && issued.evidenceBytes) {
    try {
      const type = issued.evidenceType || "";
      const image = type === "image/png" ? await doc.embedPng(issued.evidenceBytes)
        : /^image\/jpe?g$/.test(type) ? await doc.embedJpg(issued.evidenceBytes)
        : null;
      if (image) model.issued.evidence = { image };
    } catch (e) { /* listed instead of drawn; the pack still builds */ }
  }
  drawIssuedMarks(cv, model);
  const afeNo = layout.SLOTS.find((s) => s.key === "header.afeNo");
  if (afeNo) drawSlot(cv, afeNo, model);
  const ev = model.issued && model.issued.evidence;
  return {
    evidence: ev ? { onPageOne: Boolean(ev.onPageOne), overleaf: Boolean(ev.overleaf) } : null,
    // A capture whose shape will not survive the box on page one takes a page of its own, at
    // full size — AFTER the signed pages, never between them.
    addEvidencePage: ev && ev.overleaf ? () => { cv.newPage(); drawEvidencePage(cv, model); return cv.page; } : null,
  };
}

/**
 * What Fixed Assets put behind the signed AFE, and where each piece is (R156).
 *
 * The issued copy's Documents page used to be REDRAWN to add Fixed Assets' own documents, which
 * was one of the ways the issued AFE stopped being the signed one. The signed Documents page now
 * stays as it was signed, and this page — placed straight after the signed pages, before
 * anything added — says where the signed part ends and what follows, so a reader always knows
 * the whole set.
 *
 * `rows` are { filename, roleLabel, size, where }.
 */
async function drawAddedIndex(doc, page, rows, opts) {
  const o = opts || {};
  doc.registerFontkit(fontkit);
  const fonts = {
    regular: await doc.embedFont(FONT_BYTES.regular, { subset: false }),
    bold: await doc.embedFont(FONT_BYTES.bold, { subset: false }),
  };
  const cv = makeCanvas(doc, fonts).usePage(page);
  let y = pageTitle(cv, "Added by Fixed Assets");
  y = blockHeading(cv, o.signedPages > 1 ? `Pages 1–${o.signedPages} are the AFE exactly as it was signed.` : "Page 1 is the AFE exactly as it was signed.", y - 18,
    "Fixed Assets' own marks are printed in red on page 1 — the numbers and who approved the issue at the top, and the order in the AFE NO box. Nothing else on the signed pages was changed. Everything below was added when the order was issued.");
  const spec = extra.DOCUMENTS_BLOCK;
  const totalChars = spec.columns.reduce((a, c) => a + c.chars, 0);
  const unit = extra.w(0, 7) / totalChars;
  const colX = [];
  let cx = extra.x(0);
  for (const c of spec.columns) { colX.push(cx); cx += c.chars * unit; }
  y -= 6 + spec.rowHeight;
  cv.box({ x: extra.x(0), y, w: extra.w(0, 7), h: spec.rowHeight, fill: INK.head });
  spec.columns.forEach((c, i) => cv.text(c.label, { x: colX[i] + 4, y: y + 4.5, w: c.chars * unit - 6, size: SIZE.small, bold: true }));
  for (const d of rows) {
    y -= spec.rowHeight;
    cv.box({ x: extra.x(0), y, w: extra.w(0, 7), h: spec.rowHeight });
    spec.columns.forEach((c, i) => {
      const text = cv.wrap(String(d[c.key] || ""), SIZE.value, false, c.chars * unit - 8, 1)[0] || "";
      cv.text(text, { x: colX[i] + 4, y: y + 4.5, w: c.chars * unit - 8, size: SIZE.value, clip: true,
        colour: c.key === "where" && d.red ? INK.red : undefined });
    });
  }
  if (o.link && rows.some((d) => d.record) && /^https?:/i.test(o.link)) {
    y -= SIZE.note + 5;
    cv.text(`Everything not bound into this PDF is on the AFE at ${o.link}`,
      { x: extra.x(0), y, w: extra.w(0, 7), size: SIZE.note, colour: INK.hint });
  }
}

/**
 * Fixed Assets' approval for issue, as a page of the issued AFE (R168).
 *
 * Today it is an e-mail — "Approved. Please proceed with creating the AFE." — printed and bound in
 * as the last page of the issued AFE (`313469 BriCare`, page 38), and at the UAT review (2026-10-14)
 * Lyndsay asked for "the finance signature" on it, "for the audit perspective" — the person who
 * approved, by name, where the RTR_FA mailbox "will not work" (Shashank, agreeing). The tool already
 * holds everything that e-mail said, and two things it never could: that the control ran — the
 * approval is refused while a red flag is open, and the order is refused to whoever approved it —
 * and where the record of it is kept.
 *
 * Red where it is Fixed Assets' own word, as on page one: the approver and the note.
 *
 * `facts` = { afeId, title, ioNumber, byName, group, byEmail, at, note, orderBy, orderAt, auditId },
 * the times already in India time. Nothing here reads a clock, so a rebuilt pack is the same bytes.
 */
async function drawIssueApproval(doc, page, facts) {
  const f = facts || {};
  doc.registerFontkit(fontkit);
  const fonts = {
    regular: await doc.embedFont(FONT_BYTES.regular, { subset: false }),
    bold: await doc.embedFont(FONT_BYTES.bold, { subset: false }),
  };
  const cv = makeCanvas(doc, fonts).usePage(page);
  let y = pageTitle(cv, "Approval for issue");
  y = blockHeading(cv, `Approved for issue by ${f.byName || "Fixed Assets"}${f.group ? `, ${f.group}` : ""}.`, y - 18,
    "Fixed Assets' second pair of eyes before the internal order was created. It is refused while any red flag is open, "
    + "and the order is then created by somebody else.");

  const rows = [
    ["AFE", [f.afeId, f.title].filter(Boolean).join(" · ")],
    ["Internal order", f.ioNumber || ""],
    ["Approved by", [f.byName, f.group].filter(Boolean).join(" · "), true],
    ["Mailbox", f.byEmail || ""],
    ["When", f.at || ""],
    ["Note", f.note ? `“${f.note}”` : "None", Boolean(f.note)],
    ["Order created by", [f.orderBy, f.orderAt].filter(Boolean).join(", ")],
    ["On record as", f.auditId ? `Audit event ${f.auditId} in AFE Workbench, against ${f.afeId}` : `AFE Workbench, against ${f.afeId || "this AFE"}`],
  ];
  const lx = extra.x(0), lw = extra.w(0, 2), vx = extra.x(2), vw = extra.w(2, 5);
  y -= 8;
  for (const [label, value, red] of rows) {
    const lines = cv.wrap(String(value || ""), SIZE.value, Boolean(red), vw - 8, 4);
    const h = Math.max(20, 9 + lines.length * (SIZE.value + 2));
    y -= h;
    cv.box({ x: lx, y, w: lw, h, fill: INK.band });
    cv.box({ x: vx, y, w: vw, h });
    cv.text(label, { x: lx, y: y + h - SIZE.label - 5.5, w: lw, size: SIZE.label, bold: true });
    let vy = y + h - SIZE.value - 5.5;
    for (const line of lines) {
      cv.text(line, { x: vx, y: vy, w: vw, size: SIZE.value, bold: Boolean(red), colour: red ? INK.red : undefined, clip: true });
      vy -= SIZE.value + 2;
    }
  }
}

module.exports = { renderAfeForm, markIssued, drawAddedIndex, drawIssueApproval, winAnsi, DOC_DATE };
